writes.receiver:
events
          .where(
            prismaModelFilter({
              eventId: owned.eventId,
              brandId: owned.brandId,
              leaseToken: owned.leaseToken,
              leaseExpiresAt: { $gt: now },
            })
          )

baseline.receiver:
events
          .where(
            prismaModelFilter({
              eventId: owned.eventId,
              brandId: owned.brandId,
              leaseToken: owned.leaseToken,
