            })
          )

writes.receiver:
sanitizeChroniclePath(String(redactSecret(head)))
    // Credentials can be embedded in diagnostic text, including an Error's stack.
    .replace(/(\bBearer\s+)[A-Za-z0-9._~+/-]+=*/gi, '$1REDACTED')

